 useEffect(()=>{setIdentity(data?.user?.id||'visitor')},[data?.user?.id,setIdentity]);
 useEffect(()=>{setToken(new URLSearchParams(location.search).get('table'));setReady(true)},[]);
 const notify=useCallback((message:string)=>{setToast(message);clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),5000)},[]);
 const load=useCallback(async()=>{
  if(!ready)return;try{const query=token?`table=${encodeURIComponent(token)}${cap.current?`&session=${encodeURIComponent(cap.current)}`:''}`:`restaurant=${encodeURIComponent(restaurantId)}`;const res=await fetch(`/api/state?${query}`,{cache:'no-store',headers:{'Accept-Language':language}});const d:Any=await res.json();if(!res.ok)throw new Error(d.errorKey||d.error);if(token&&d.session&&!cap.current)cap.current=d.session.capability;
  if(!token&&d.restaurant){const n=d.restaurant.orders.length;if(lastOrders.current!==null&&n>lastOrders.current)notify('New order received · check the orders queue');lastOrders.current=n;}setData(d);setError('');setOffline(false)}catch(e:Any){setOffline(true);setError(e instanceof TypeError?'Network error. Please check your connection.':e.message)}
 },[ready,token,restaurantId,notify,language]);
 useEffect(()=>{load();const id=setInterval(load,2000);const refresh=()=>load();window.addEventListener('online',refresh);return()=>{clearInterval(id);window.removeEventListener('online',refresh)}},[load]);
