 {current==='menu'&&<><div className="section-bar"><div className="segment"><span>{t.menu.length}{' '}{tr("items ·")}{' '}{t.menu.filter((m:Any)=>m.available).length}{' '}{tr("available")}</span></div><label className="search"><Search size={16}/><input aria-label={tr("Search the menu…")} placeholder={tr("Search the menu…")} value={search} onChange={e=>setSearch(e.target.value)}/></label></div>{t.categories.map((category:string)=><section className="menu-category" key={category}><h2>{language==='ar'?t.categoryNames?.[category]||tr(category):(language==='ar'?t.categoryNames?.[category]||tr(category):category)}</h2><div className="menu-admin-grid">{t.menu.filter((m:Any)=>m.category===category&&[m.name,m.nameAr||''].some(name=>name.toLowerCase().includes(search.toLowerCase()))).map((m:Any)=><article className="menu-admin-card" key={m.id}>{m.image?<img src={m.image} alt={content(m)}/>:<div className="image-placeholder"><UtensilsCrossed/></div>}<div><div className="panel-title"><h3>{content(m)}</h3>{!m.visible&&<Badge status="disabled">{tr("Hidden")}</Badge>}</div><p>{content(m,'description')}</p><strong>{money(m.price)} <small>{tr("EGP")}</small></strong><div className="menu-actions"><button role="switch" aria-checked={m.available} disabled={!has('menu.write')||busy} className={`availability ${m.available?'on':''}`} onClick={()=>act('menu.availability',{itemId:m.id,available:!m.available})}><i/>{m.available?tr("Available"):tr("Out of stock")}</button>{has('menu.write')&&<button className="text-button" onClick={()=>setModal({type:'menu',item:m})}>{tr("Edit item")}{' '}<ArrowUpRight size={14}/></button>}</div></div></article>)}</div></section>)}</>}

