 {current==='staff'&&<div className="list-panel"><div className="list-header"><h2>{tr("Your team")}</h2><span>{tr("Permissions are individually configurable")}</span></div>{t.members.map((m:Any)=><div className="request-row" key={m.id}><span className="avatar">{m.name[0].toUpperCase()}</span><div><h3>{content(m)}</h3><p>{m.email}</p><small>{m.permissions.length}{' '}{tr("permissions ·")}{' '}{m.userId?tr("Account connected"):tr("Awaiting first sign-in")}</small></div><Badge status={m.active?'active':'disabled'}/><button className="button small" onClick={()=>setModal({type:'staff',member:m})}>{tr("Manage access")}{' '}<SlidersHorizontal size={14}/></button></div>)}</div>}

 {current==='feedback'&&<><div className="privacy-note"><Lock size={17}/>{' '}{tr("Private to authorized management. Feedback never delays the bill.")}</div><div className="feedback-grid">{t.feedback.slice().reverse().map((f:Any)=><article key={f.id} className="feedback-card"><div className="stars">{'★'.repeat(f.rating)}<span>{'★'.repeat(5-f.rating)}</span></div><p>{f.comment||tr("A rating, with no additional comment.")}</p><small>{tr("Table")}{' '}{t.tables.find((tb:Any)=>tb.id===f.tableId)?.label} · {date(f.createdAt)} · {time(f.createdAt)}</small></article>)}</div>{t.feedback.length===0&&<Empty icon={Star} title={tr("Good service starts with listening")}>{tr("Private guest feedback will appear here.")}</Empty>}</>}

 {current==='activity'&&<div className="list-panel"><div className="list-header"><h2>{tr("Recent activity")}</h2><span>{tr("Latest 150 events")}</span></div>{t.audit.map((a:Any)=><div className="audit-row" key={a.id}><span className="status-dot available"/><div><strong>{tr(a.action)}</strong><p>{auditDetail(a)}</p><small>{a.by}</small></div><time>{date(a.at)} {time(a.at)}</time></div>)}{!t.audit.length&&<Empty title={tr("A fresh start")}>{tr("Session, order, payment and management actions will be recorded here.")}</Empty>}</div>}

