function Stat({label,value,caption,icon:Icon}:Any){
 const {t:tr,money,time,elapsed,language,content,date,setIdentity,error:localizeError,auditDetail}=useI18n();
return <div className="stat"><div><span>{label}</span><Icon size={19}/></div><strong>{value}</strong><p>{caption}</p></div>}
function BillTotals({b}:Any){
 const {t:tr,money,time,elapsed,language,content,date,setIdentity,error:localizeError,auditDetail}=useI18n();
if(!b)return null;return <div className="bill-totals"><div><span>{tr("Subtotal")}</span><span>{money(b.subtotal)}{' '}{tr("EGP")}</span></div>{b.service>0&&<div><span>{tr("Service charge")}</span><span>{money(b.service)}{' '}{tr("EGP")}</span></div>}{b.tax>0&&<div><span>{tr("Tax")}</span><span>{money(b.tax)}{' '}{tr("EGP")}</span></div>}<div className="total"><strong>{tr("Table total")}</strong><strong>{money(b.total)} <small>{tr("EGP")}</small></strong></div>{b.paid>0&&<div><span>{tr("Recorded payment")}</span><span>− {money(b.paid)}{' '}{tr("EGP")}</span></div>}{b.paid>0&&<div><strong>{tr("Remaining")}</strong><strong>{money(b.due)}{' '}{tr("EGP")}</strong></div>}</div>}
function OrderCard({order:o,table,has=()=>false,busy,onStatus,guestEdit}:Any){
 const {t:tr,money,time,elapsed,language,content,date,setIdentity,error:localizeError,auditDetail}=useI18n();
return <article className="order-card"><div className="panel-title"><div><h3>{tr("Order #")}{String(o.number).padStart(3,'0')}</h3><span className="muted">{table?tr("Table {p0} · ",{p0:table.label}):''}{time(o.createdAt)}</span></div><Badge status={o.status}/></div><div className="order-lines">{o.lines.map((l:Any)=><div key={l.id}><span className="qty">{l.quantity}</span><div><strong>{content(l)}</strong>{l.modifiers.length>0&&<small>{l.modifiers.map((m:Any)=>content(m)).join(' · ')}</small>}{l.notes&&<p className="order-note">{l.notes}</p>}</div></div>)}</div><div className="order-bottom"><span>{tr("v")}{o.version} · {elapsed(o.createdAt)}</span><strong>{money(orderTotal(o))}{' '}{tr("EGP")}</strong></div>{guestEdit&&['PENDING','ACCEPTED'].includes(o.status)&&<button className="button full" onClick={guestEdit}>{tr("Edit this order")}</button>}{guestEdit&&!['PENDING','ACCEPTED'].includes(o.status)&&<div className="locked"><Lock size={13}/>{tr("Preparation started · order locked")}</div>}{onStatus&&<div className="order-actions">{o.status==='PENDING'&&has('orders.manage')&&<button className="button small" disabled={busy} onClick={()=>onStatus('ACCEPTED')}>{tr("Accept")}</button>}{['PENDING','ACCEPTED'].includes(o.status)&&has('kitchen.start_preparing')&&<button className="button primary full" disabled={busy} onClick={()=>onStatus('PREPARING')}><ChefHat size={16}/>{tr("Start preparing")}</button>}{o.status==='PREPARING'&&has('kitchen.mark_ready')&&<button className="button primary full" disabled={busy} onClick={()=>onStatus('READY')}><Check size={16}/>{tr("Mark ready")}</button>}{o.status==='READY'&&has('orders.manage')&&<button className="button primary full" disabled={busy} onClick={()=>onStatus('SERVED')}>{tr("Mark served")}{' '}<CheckCheck size={16}/></button>}</div>}</article>}

function SettingsForm({t,busy,save}:Any){
 const {t:tr,money,time,elapsed,language,content,date,setIdentity,error:localizeError,auditDetail}=useI18n();
const [values,setValues]=useState({name:t.name,nameAr:t.nameAr||'',tagline:t.tagline,taglineAr:t.taglineAr||'',taxBps:t.taxBps,serviceBps:t.serviceBps});return <form className="settings-form" onSubmit={e=>{e.preventDefault();save(values)}}><h2>{tr("Restaurant identity")}</h2><Field label={tr("Restaurant name")}><input required value={values.name} onChange={e=>setValues({...values,name:e.target.value})}/></Field><Field label={tr("Restaurant name (Arabic)")}><input dir="rtl" value={values.nameAr} onChange={e=>setValues({...values,nameAr:e.target.value})}/></Field><Field label={tr("Guest welcome line")}><input value={values.tagline} onChange={e=>setValues({...values,tagline:e.target.value})}/></Field><Field label={tr("Welcome line (Arabic)")}><input dir="rtl" value={values.taglineAr} onChange={e=>setValues({...values,taglineAr:e.target.value})}/></Field><p>{tr("Website design is managed by Tap2Serve.")}</p><h2>{tr("Receipt settings")}</h2><p>{tr("Rates apply to the subtotal independently and are fixed when a new session opens. Existing sessions keep their agreed rates. Currency: EGP.")}</p><div className="form-grid"><Field label={tr("Tax (%)")}><input type="number" min="0" max="100" step="0.01" value={values.taxBps/100} onChange={e=>setValues({...values,taxBps:Math.round(+e.target.value*100)})}/></Field><Field label={tr("Service charge (%)")}><input type="number" min="0" max="100" step="0.01" value={values.serviceBps/100} onChange={e=>setValues({...values,serviceBps:Math.round(+e.target.value*100)})}/></Field></div><button className="button primary" disabled={busy}>{tr("Save settings")}{' '}<Check size={16}/></button></form>}

