 const {t:tr,money,time,elapsed,language,content,date,setIdentity,error:localizeError,auditDetail}=useI18n();

 const [page,setPage]=useState('menu'),[category,setCategory]=useState('All'),[basket,setBasket]=useState<Any[]>([]),[modal,setModal]=useState<Any>(null),[editing,setEditing]=useState<Any>(null),[rating,setRating]=useState(0),[comment,setComment]=useState('');
