 {ordering&&basket.length>0&&page==='menu'&&<button className="basket-float" onClick={()=>setModal({type:'basket'})}><span className="basket-count">{count}</span><strong>{editing?tr("Edit order #{p0}",{p0:editing.number}):tr("View your basket")}</strong><span>{money(total)}{' '}{tr("EGP")}{' '}<ArrowRight size={17}/></span></button>}
